+    @Override
+    public Num calculate(BarSeries series, TradingRecord tradingRecord) {
+        var cashFlow = new CashFlow(series, tradingRecord);
+        return Drawdown.amount(series, tradingRecord, cashFlow);
+    }
+
+    /**
